INSERT INTO build_task (task_id, task_rank, title, owner_lane, rationale, status, boundary) VALUES ('task_promote_confirmed_reference_data', 2, 'Promote confirmed Data Room reference answers', 'Cassandra / Codex', 'Hydration is blocked until confirmed reference data exists.', 'blocked_until_operator_confirmation', 'No provisional answer becomes runtime truth automatically.');
INSERT INTO build_task (task_id, task_rank, title, owner_lane, rationale, status, boundary) VALUES ('task_live_chatgpt_adapter_readiness', 3, 'Prove or reject live ChatGPT 5.5 advisory adapter', 'Hermes / Guardian', 'Manual form-fill package is ready, but live adapter claims must fail closed.', 'future_gated', 'No external model call without explicit approved adapter and receipts.');
INSERT INTO build_task (task_id, task_rank, title, owner_lane, rationale, status, boundary) VALUES ('task_map_import_gap', 4, 'Resolve Mac map import gap separately', 'PC/Mac Sync', 'Map import was explicitly separate from read-model sync repair.', 'separate_lane_required', 'Registry does not run sync or Mac jobs.');
INSERT INTO build_task (task_id, task_rank, title, owner_lane, rationale, status, boundary) VALUES ('task_voice_caveat', 5, 'Keep voice/Kokoro caveat separate', 'Cassandra', 'Text route is canonical and voice side effects should not block core operator workflows.', 'known_caveat', 'No voice fix or daemon start here.');
INSERT INTO build_task (task_id, task_rank, title, owner_lane, rationale, status, boundary) VALUES ('task_correspondence_watcher', 6, 'Wire correspondence watcher loop safely', 'PC Codex', 'PC-9 remains: watch, understand, calendar-aware draft, gate; Gmail scope must be explicit.', 'pending_send_hold_safetied', 'No Gmail body reading without scope decision; no email send.');
INSERT INTO build_task (task_id, task_rank, title, owner_lane, rationale, status, boundary) VALUES ('task_email_send_executor_scaffold', 7, 'Scaffold email_send executor unregistered', 'PC Codex', 'PC-10 remains: approved packet to email brain to side-effect receipt, but SEND_HOLD prevents firing.', 'pending_send_hold_safetied', 'Executor must remain unregistered and non-firing until tested and approved.');
INSERT INTO build_task (task_id, task_rank, title, owner_lane, rationale, status, boundary) VALUES ('task_land_reynolds_gig', 8, 'Land Reynolds gig as canonical business record', 'PC Codex', 'PC-16 should dogfood gig intake by moving Reynolds facts from share artifact to canonical ledger.', 'completed_pc16', 'Recorded candidate gig/canonical fact only; no send or invoice execution.');
INSERT INTO build_task (task_id, task_rank, title, owner_lane, rationale, status, boundary) VALUES ('task_refresh_graphiffy_atlas', 9, 'Refresh atlas/Graphiffy after compose/orchestration wiring', 'PC Codex', 'PC-17 should make graph artifacts reflect compose/API/orchestration reality.', 'pending', 'Use established local generator only; no external API or service mutation.');
